import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel 6353c49:
# packet.MovePlayer{EntityRuntimeID: 2, Position: {1, 2, 3}, Pitch: 4, Yaw: 5,
#   HeadYaw: 6, Mode: packet.MoveModeTeleport, OnGround: true,
#   RiddenEntityRuntimeID: 0, TeleportCause: 3, TeleportSourceEntityType: 42, Tick: 100}
V1001_TELEPORT = bytes.fromhex("020000803f0000004000004040000080400000a0400000c040020100030000002a00000064")

# generated by gophertunnel 6353c49:
# packet.MovePlayer{EntityRuntimeID: 2, Position: {1, 2, 3}, Pitch: 4, Yaw: 5,
#   HeadYaw: 6, Mode: packet.MoveModeNormal, OnGround: true,
#   RiddenEntityRuntimeID: 0, Tick: 100}
V1001_NORMAL = bytes.fromhex("020000803f0000004000004040000080400000a0400000c04000010064")

# generated by gophertunnel b8bd735:
# packet.MovePlayer{EntityRuntimeID: 2, Position: {1, 2, 3}, Pitch: 4, Yaw: 5, HeadYaw: 6,
#   Mode: packet.MoveModeTeleport, OnGround: true, RiddenEntityRuntimeID: 0,
#   TeleportData: protocol.Option(protocol.TeleportData{TeleportCause: packet.TeleportCauseCommand,
#     TeleportSourceEntityType: 42}), Tick: 100}
V2168_TELEPORT = bytes.fromhex("020000803f0000004000004040000080400000a0400000c04002010001030000002a00000064")

# generated by gophertunnel b8bd735:
# packet.MovePlayer{EntityRuntimeID: 2, Position: {1, 2, 3}, Pitch: 4, Yaw: 5, HeadYaw: 6,
#   Mode: packet.MoveModeNormal, OnGround: true, RiddenEntityRuntimeID: 0, Tick: 100}
V2168_NORMAL = bytes.fromhex("020000803f0000004000004040000080400000a0400000c0400001000064")

TELEPORT = v1001.PlayerPositionModeComponent.PositionMode.TELEPORT
NORMAL = v1001.PlayerPositionModeComponent.PositionMode.NORMAL

BODY = {
    "player_id": 2,
    "pos": v1001.Vec3(x=1.0, y=2.0, z=3.0),
    "rot": v1001.Vec2(x=4.0, y=5.0),
    "y_head_rot": 6.0,
    "on_ground": True,
    "riding_id": 0,
    "tick": 100,
}

GOLDENS = [
    pytest.param(
        v1001.MovePlayerPacket(**BODY, reset_position=TELEPORT, cause=3, source_entity_type=42),
        V1001_TELEPORT,
        id="v1001-teleport",
    ),
    pytest.param(v1001.MovePlayerPacket(**BODY, reset_position=NORMAL), V1001_NORMAL, id="v1001-normal"),
    pytest.param(
        v2168.MovePlayerPacket(
            **BODY,
            reset_position=TELEPORT,
            teleport_data=v2168.MovePlayerTeleportData(cause=3, source_entity_type=42),
        ),
        V2168_TELEPORT,
        id="v2168-teleport",
    ),
    pytest.param(
        v2168.MovePlayerPacket(**BODY, reset_position=NORMAL, teleport_data=None),
        V2168_NORMAL,
        id="v2168-normal",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_move_player_is_packet_19(version):
    assert version.PACKETS[19] is version.MovePlayerPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_move_player_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_move_player_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_v1001_leaves_the_teleport_pair_off_the_wire_in_any_other_mode():
    packet = v1001.MovePlayerPacket(**BODY, reset_position=NORMAL, cause=3, source_entity_type=42)
    assert bytes(packet) == V1001_NORMAL


def test_v1001_forgets_the_teleport_pair_a_normal_mode_body_never_carried():
    packet = v1001.MovePlayerPacket.from_bytes(V1001_NORMAL)
    assert (packet.cause, packet.source_entity_type) == (0, 0)


def test_v2168_rejects_a_v1001_teleport_body():
    with pytest.raises(ValueError, match="at byte"):
        v2168.MovePlayerPacket.from_bytes(V1001_TELEPORT)


def test_v1001_rejects_a_v2168_teleport_body_as_trailing_bytes():
    with pytest.raises(ValueError, match="trailing bytes"):
        v1001.MovePlayerPacket.from_bytes(V2168_TELEPORT)
